kit.wpool/queue.py:
"""A bounded work queue."""
import threading


class Full(Exception):
    pass


class Closed(Exception):
    pass


class Queue:
    def __init__(self, maxsize=0):
        self.maxsize = maxsize
        self._items = []
        self._closed = False
        self._unfinished = 0

    def get(self):
        if not self._items:
            return None
        self._unfinished += 1
        return self._items.pop(0)

    def put(self, item):
        self._items.append(item)

    def task_done(self):
        self._unfinished -= 1

    def close(self):
        self._closed = True

kit.cachebox/lru.py:
"""Least-recently-used cache."""


class LRU:
    def __init__(self, capacity):
        self.capacity = capacity
        self._data = {}
        self._order = []

    def get(self, key):
        return self._data.get(key)

    def put(self, key, value):
        if key in self._data:
            self._order.remove(key)
        self._data[key] = value
        self._order.append(key)
        if self.capacity and len(self._order) > self.capacity:
            old = self._order.pop(0)
            self._data.pop(old, None)

    def keys(self):
        return list(reversed(self._order))

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._data

kit.apiwrap/client.py:
"""HTTP client with retries."""
import time


class Transient(Exception):
    pass


class Client:
    def __init__(self, transport, backoff=0.01):
        self.transport = transport
        self.backoff = backoff

    def call(self, method, path, body=None, timeout=1.0, attempts=3):
        for i in range(attempts):
            if i:
                time.sleep(self.backoff * 2 ** (i - 1))
            r = self.transport(method, path, body)
            return r
        raise Transient('unreachable')

