class SessionError(Exception):
    pass


class UnknownSession(SessionError):
    pass


class SessionStore:
    def __init__(self, ttl=3600):
        self.ttl = ttl
        self._data = {}

    def get(self, sid):
        if sid not in self._data:
            raise UnknownSession(sid)
        return self._data[sid]

    def set(self, sid, value):
        self._data[sid] = [value, time.monotonic()]

    def delete(self, sid):
        self._data.pop(sid, None)

    def touch(self, sid):
        self._data[sid][1] = time.monotonic()

    def clear(self):
