    pass


class Aggregate:
    def __init__(self):
        self.state = {'count': 0, 'total': 0}
        self.version = 0
        self.pending = []

    def apply(self, event):
        if event.get('name') == 'added':
            self.state['count'] += 1
            self.state['total'] += event['amount']
            self.version += 1
            return
        raise InvalidEvent(event.get('name'))

